// Jinx UI export/prop names below are assumed (TextField/Select/Switch/Button, value-based onChange) — verify against the installed @jinx-ui/react version.
import { useState } from 'react';
import { Button, Form, Select, Stack, Switch, TextField } from '@jinx-ui/react';

export type ProfileSettings = {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
};

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileSettings['language']>(
    initialSettings?.language ?? 'ru',
  );
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  };

  return (
    <Form onSubmit={handleSubmit}>
      <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
        <TextField
          id="profile-name"
          label="Имя"
          value={name}
          onChange={setName}
          autoComplete="name"
        />

        <Select
          id="profile-language"
          label="Язык интерфейса"
          value={language}
          options={LANGUAGE_OPTIONS}
          onChange={(value: string) => setLanguage(value as ProfileSettings['language'])}
        />

        <Switch
          id="profile-email-notifications"
          label="Уведомления на почту"
          checked={emailNotifications}
          onChange={setEmailNotifications}
        />

        <Button type="submit" variant="primary">
          Сохранить
        </Button>
      </Stack>
    </Form>
  );
}

export default ProfileSettingsForm;

